use vstd::prelude::*;

verus! {

spec fn count_true_seq(s: Seq<bool>) -> nat
    decreases s.len(),
{
    if s.len() == 0 {
        0
    } else {
        count_true_seq(s.drop_last()) + if s.last() { 1 } else { 0 }
    }
}

fn count_true(arr: &Vec<bool>) -> (count: u64)
    requires
        count_true_seq(arr@) <= u64::MAX as nat,
    ensures
        count as nat == count_true_seq(arr@),
{
    let mut count: u64 = 0;

    for &b in arr.iter()
        invariant
            // `arr` is unchanged by the loop
            arr@ == old(arr@),
            // count matches the number of trues in the processed prefix
            count as nat == count_true_seq(arr@.subrange(0, index as int)),
            // stays in range
            count_true_seq(arr@) <= u64::MAX as nat,
            // loop index is within bounds
            0 <= index <= arr@.len(),
    {
        if b {
            // show we don't overflow u64 on increment
            assert(count < u64::MAX) by {
                // From the invariant, count is at most the total number of trues in the whole array
                assert(count as nat <= count_true_seq(arr@));
            }
            count += 1;
        }
        // After each iteration, `count` equals the number of `true` values
        // in the prefix processed so far.
    }

    count
}

} // verus!

